mapper.select:
SELECT count(*) FROM t_agent_account a1 LEFT JOIN t_agent_account a2 ON a1.parent_agent_code = a2.agent_code LEFT JOIN sys_user s on a1.sys_user_id = s.user_id LEFT JOIN t_withdrawal_record r on a1.agent_code = r.agent_code WHERE a1.sys_user_id != 1
AND a2.agent_name like concat('%', #{parentAgentName}, '%')
AND a1.agent_name like concat('%', #{agentName}, '%')
AND a1.is_real_name = #{isRealName}
AND a1.is_enabled = #{isEnabled}
AND a1.level = #{level}
ORDER BY a1.create_time desc

SELECT a1.agent_account_id as agentAccountId, s.user_id as sysUserId, s.user_name as sysUserName, a1.parent_agent_code as parentAgentCode, a2.agent_name as parentAgentName, a1.agent_code as agentCode, a1.agent_name as agentName, a1.level as level, a1.is_real_name as isRealName, a1.phone as phone, a1.is_enabled as isEnabled, a1.is_encrypt as isEncrypt, a1.create_time as createTime, r.balance as balance FROM t_agent_account a1 LEFT JOIN t_agent_account a2 ON a1.parent_agent_code = a2.agent_code LEFT JOIN sys_user s on a1.sys_user_id = s.user_id LEFT JOIN t_withdrawal_record r on a1.agent_code = r.agent_code WHERE a1.sys_user_id != 1
AND a2.agent_name like concat('%', #{parentAgentName}, '%')
AND a1.agent_name like concat('%', #{agentName}, '%')
AND a1.is_real_name = #{isRealName}
AND a1.is_enabled = #{isEnabled}
AND a1.level = #{level}
ORDER BY a1.create_time desc limit #{offset},#{pageSize}

SELECT agentCode, agentName, totalOrders, activatedOrders, totalCommission, downstreamAgentCount, ROW_NUMBER() OVER (ORDER BY totalOrders DESC, createTime ASC) as ranking FROM ( SELECT a.agent_code as agentCode, a.agent_name as agentName, a.create_time as createTime, COALESCE(o.total_orders, 0) as totalOrders, COALESCE(o.activated_orders, 0) as activatedOrders, COALESCE(commission.total_commission, 0) as totalCommission, COALESCE(downstream.downstream_count, 0) as downstreamAgentCount FROM t_agent_account a LEFT JOIN ( SELECT downstream_code, COUNT(*) as total_orders, SUM(CASE WHEN order_status = 4 THEN 1 ELSE 0 END) as activated_orders FROM t_order WHERE 1=1
AND create_time >= #{startTime} AND create_time <= #{endTime}
GROUP BY downstream_code ) o ON a.agent_code = o.downstream_code LEFT JOIN ( SELECT downstream_agent_code, SUM(CASE WHEN order_status = 4 AND order_commission_status = 3 THEN product_commission ELSE 0 END) as total_commission FROM t_order_commission WHERE 1=1
AND order_create_time >= #{startTime} AND order_create_time <= #{endTime}
GROUP BY downstream_agent_code ) commission ON a.agent_code = commission.downstream_agent_code LEFT JOIN ( SELECT parent_agent_code, COUNT(*) as downstream_count FROM t_agent_account WHERE parent_agent_code IS NOT NULL AND parent_agent_code != '' GROUP BY parent_agent_code ) downstream ON a.agent_code = downstream.parent_agent_code WHERE a.sys_user_id != 1
AND a.agent_name LIKE CONCAT('%', #{agentName}, '%')
) ranked_agents ORDER BY totalOrders DESC, createTime ASC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM t_agent_account a1
WHERE a1.parent_agent_code = #{queryBO.parentAgentCode}
  AND a1.sys_user_id != 1

    AND (
        CAST(a1.agent_account_id AS CHAR) LIKE CONCAT('%', #{queryBO.searchKeyword}, '%')
        OR a1.agent_code LIKE CONCAT('%', #{queryBO.searchKeyword}, '%')
        OR a1.agent_name LIKE CONCAT('%', #{queryBO.searchKeyword}, '%')
        OR a1.phone LIKE CONCAT('%', #{queryBO.searchKeyword}, '%')
    )


    AND a1.is_real_name = #{queryBO.isRealName}


    AND a1.is_enabled = #{queryBO.isEnabled}


    AND a1.level = #{queryBO.level}

SELECT a1.agent_account_id as agentAccountId, a1.sys_user_id as sysUserId, s.user_name as sysUserName, a1.parent_agent_code as parentAgentCode, a2.agent_name as parentAgentName, a1.agent_code as agentCode, a1.agent_name as agentName, a1.level as level, a1.is_real_name as isRealName, a1.phone as phone, a1.is_enabled as isEnabled, a1.is_encrypt as isEncrypt, a1.create_time as createTime, r.balance as balance FROM t_agent_account a1 LEFT JOIN t_agent_account a2 ON a1.parent_agent_code = a2.agent_code LEFT JOIN sys_user s ON a1.sys_user_id = s.user_id LEFT JOIN t_withdrawal_record r ON a1.agent_code = r.agent_code WHERE a1.parent_agent_code = #{queryBO.parentAgentCode} AND a1.sys_user_id != 1
AND ( CAST(a1.agent_account_id AS CHAR) LIKE CONCAT('%', #{queryBO.searchKeyword}, '%') OR a1.agent_code LIKE CONCAT('%', #{queryBO.searchKeyword}, '%') OR a1.agent_name LIKE CONCAT('%', #{queryBO.searchKeyword}, '%') OR a1.phone LIKE CONCAT('%', #{queryBO.searchKeyword}, '%') )
AND a1.is_real_name = #{queryBO.isRealName}
AND a1.is_enabled = #{queryBO.isEnabled}
AND a1.level = #{queryBO.level}
ORDER BY a1.create_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM t_agent_account
WHERE parent_agent_code = #{parentAgentCode}

SELECT COUNT(*)
FROM t_agent_account
WHERE parent_agent_code = #{agentCode}
  AND create_time >= #{startTime}
  AND create_time <= #{endTime}

SELECT COUNT(*)
FROM t_agent_account
WHERE parent_agent_list LIKE CONCAT('%', #{agentCode}, '%')
  AND create_time >= #{startTime}
  AND create_time <= #{endTime}

SELECT ROW_NUMBER() OVER (ORDER BY SUM(ocd.revenue_product_commission) DESC) as ranking, a.agent_code as agentCode, a.agent_name as agentName, a.level as level, SUM(ocd.revenue_product_commission) as statValue FROM t_order_commission_details ocd INNER JOIN t_agent_account a ON ocd.agent_code = a.agent_code INNER JOIN t_order_commission oc ON ocd.order_commission_id = oc.order_commission_id WHERE oc.order_commission_status = 3 AND ocd.create_time >= #{queryBO.startTime} AND ocd.create_time <= #{queryBO.endTime}
AND a.parent_agent_list LIKE CONCAT('%', #{queryBO.parentAgentCode}, '%')
GROUP BY a.agent_code, a.agent_name, a.level ORDER BY statValue DESC LIMIT #{queryBO.topCount}

SELECT ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) as ranking, a.agent_code as agentCode, a.agent_name as agentName, a.level as level, COUNT(*) as statValue FROM t_order o INNER JOIN t_agent_account a ON o.downstream_code = a.agent_code WHERE o.create_time >= #{queryBO.startTime} AND o.create_time <= #{queryBO.endTime}
AND a.parent_agent_list LIKE CONCAT('%', #{queryBO.parentAgentCode}, '%')
GROUP BY a.agent_code, a.agent_name, a.level ORDER BY statValue DESC LIMIT #{queryBO.topCount}

SELECT ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) as ranking, a.agent_code as agentCode, a.agent_name as agentName, a.level as level, COUNT(*) as statValue FROM t_order o INNER JOIN t_agent_account a ON o.downstream_code = a.agent_code WHERE o.active_time >= #{queryBO.startTime} AND o.active_time <= #{queryBO.endTime} AND o.active_time IS NOT NULL AND o.active_time > 0 AND o.order_status = 4
AND a.parent_agent_list LIKE CONCAT('%', #{queryBO.parentAgentCode}, '%')
GROUP BY a.agent_code, a.agent_name, a.level ORDER BY statValue DESC LIMIT #{queryBO.topCount}

SELECT ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) as ranking, a.agent_code as agentCode, a.agent_name as agentName, a.level as level, COUNT(*) as statValue FROM t_agent_account sub INNER JOIN t_agent_account a ON sub.parent_agent_code = a.agent_code WHERE sub.create_time >= #{queryBO.startTime} AND sub.create_time <= #{queryBO.endTime}
AND a.parent_agent_list LIKE CONCAT('%', #{queryBO.parentAgentCode}, '%')
GROUP BY a.agent_code, a.agent_name, a.level ORDER BY statValue DESC LIMIT #{queryBO.topCount}

choose.when:
SELECT ROW_NUMBER() OVER (ORDER BY COALESCE(SUM(ocd.commission_amount), 0) DESC) as ranking, a.agent_code as agentCode, a.agent_name as agentName, a.level as level, COALESCE(SUM(ocd.commission_amount), 0) as statValue FROM t_agent_account a LEFT JOIN t_order_commission_details ocd ON a.agent_code = ocd.agent_code LEFT JOIN t_order o ON ocd.order_id = o.id WHERE 1=1
AND a.agent_name LIKE CONCAT('%', #{agentName}, '%')
AND o.create_time >= #{startTime} AND o.create_time <= #{endTime}
GROUP BY a.agent_code, a.agent_name, a.level ORDER BY statValue DESC LIMIT #{offset}, #{pageSize}

SELECT ROW_NUMBER() OVER (ORDER BY COUNT(o.id) DESC) as ranking, a.agent_code as agentCode, a.agent_name as agentName, a.level as level, COUNT(o.id) as statValue FROM t_agent_account a LEFT JOIN t_order o ON a.agent_code = o.agent_code WHERE 1=1
AND a.agent_name LIKE CONCAT('%', #{agentName}, '%')
AND o.create_time >= #{startTime} AND o.create_time <= #{endTime}
GROUP BY a.agent_code, a.agent_name, a.level ORDER BY statValue DESC LIMIT #{offset}, #{pageSize}

SELECT ROW_NUMBER() OVER (ORDER BY COUNT(o.id) DESC) as ranking, a.agent_code as agentCode, a.agent_name as agentName, a.level as level, COUNT(o.id) as statValue FROM t_agent_account a LEFT JOIN t_order o ON a.agent_code = o.agent_code WHERE 1=1
AND a.agent_name LIKE CONCAT('%', #{agentName}, '%')
AND o.create_time >= #{startTime} AND o.create_time <= #{endTime}
AND o.status = 1 GROUP BY a.agent_code, a.agent_name, a.level ORDER BY statValue DESC LIMIT #{offset}, #{pageSize}

SELECT ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) as ranking, a.agent_code as agentCode, a.agent_name as agentName, a.level as level, COUNT(*) as statValue FROM t_agent_account sub INNER JOIN t_agent_account a ON sub.parent_agent_code = a.agent_code WHERE 1=1
AND a.agent_name LIKE CONCAT('%', #{agentName}, '%')
AND sub.create_time >= #{startTime} AND sub.create_time <= #{endTime}
GROUP BY a.agent_code, a.agent_name, a.level ORDER BY statValue DESC LIMIT #{offset}, #{pageSize}

mapper.select:
SELECT COUNT(*)
FROM t_agent_account a1
LEFT JOIN sys_user s ON a1.sys_user_id = s.user_id
LEFT JOIN t_withdrawal_record r ON a1.agent_code = r.agent_code
WHERE a1.parent_agent_code = #{parentAgentCode}

    AND a1.agent_name LIKE CONCAT('%', #{agentName}, '%')


    AND a1.is_real_name = #{isRealName}


    AND a1.is_enabled = #{isEnabled}


    AND a1.level = #{level}

SELECT a1.agent_account_id as agentAccountId, s.user_id as sysUserId, s.user_name as sysUserName, a1.parent_agent_code as parentAgentCode, a1.agent_code as agentCode, a1.agent_name as agentName, a1.level as level, a1.is_real_name as isRealName, a1.phone as phone, a1.is_enabled as isEnabled, a1.is_encrypt as isEncrypt, a1.create_time as createTime, r.balance as balance, COALESCE(team_stats.team_cnt, 0) as teamCnt FROM t_agent_account a1 LEFT JOIN sys_user s ON a1.sys_user_id = s.user_id LEFT JOIN t_withdrawal_record r ON a1.agent_code = r.agent_code LEFT JOIN ( SELECT parent_agent_code, COUNT(*) as team_cnt FROM t_agent_account WHERE parent_agent_code IS NOT NULL GROUP BY parent_agent_code ) team_stats ON a1.agent_code = team_stats.parent_agent_code WHERE a1.parent_agent_code = #{parentAgentCode}
AND a1.agent_name LIKE CONCAT('%', #{agentName}, '%')
AND a1.is_real_name = #{isRealName}
AND a1.is_enabled = #{isEnabled}
AND a1.level = #{level}
ORDER BY a1.create_time DESC LIMIT #{offset}, #{pageSize}

SELECT a1.agent_account_id as agentAccountId, s.user_id as sysUserId, s.user_name as sysUserName, a1.parent_agent_code as parentAgentCode, a1.agent_code as agentCode, a1.agent_name as agentName, a1.level as level, a1.is_real_name as isRealName, a1.phone as phone, a1.is_enabled as isEnabled, a1.is_encrypt as isEncrypt, a1.create_time as createTime, r.balance as balance, COALESCE(COUNT(a2.agent_code), 0) as teamCnt FROM t_agent_account a1 LEFT JOIN sys_user s ON a1.sys_user_id = s.user_id LEFT JOIN t_withdrawal_record r ON a1.agent_code = r.agent_code LEFT JOIN t_agent_account a2 ON a1.agent_code = a2.parent_agent_code WHERE a1.parent_agent_code = #{parentAgentCode}
AND a1.agent_name LIKE CONCAT('%', #{agentName}, '%')
AND a1.is_real_name = #{isRealName}
AND a1.is_enabled = #{isEnabled}
AND a1.level = #{level}
GROUP BY a1.agent_account_id, s.user_id, s.user_name, a1.parent_agent_code, a1.agent_code, a1.agent_name, a1.level, a1.is_real_name, a1.phone, a1.is_enabled, a1.is_encrypt, a1.create_time, r.balance ORDER BY a1.create_time DESC LIMIT #{offset}, #{pageSize}
